const money=(label,hint='Kwota PLN. Wpisz własną wartość, także 0.')=>({kind:'money',label,hint,schema:{type:'string',pattern:'^\\d{1,10}(\\.\\d{1,2})?$'}});
const number=(label,min,max,hint='',integer=false)=>({kind:integer?'integer':'number',label,hint,schema:{type:integer?'integer':'number',minimum:min,maximum:max}});
const choice=(label,options,hint='')=>({kind:'select',label,options,hint,schema:{type:'string',enum:options.map(o=>o[0])}});
const json=(label,shape,hint,example)=>({kind:'json',label,hint,schema:shape,example});
const moneySchema={type:'string',pattern:'^\\d{1,10}(\\.\\d{1,2})?$'};
